/* ==========================================================================
   WeBox — design system
   Tokens → base → components → layouts → responsive
   Single coherent dark-on-light palette, warm accent.
   ========================================================================== */

:root {
  /* palette */
  --accent: #ff6b35;
  --accent-strong: #d94f1b;
  --accent-soft: #fff1ea;
  --accent-ring: rgba(255, 107, 53, .35);

  --ink: #1b1f24;
  --ink-2: #3d4550;
  --muted: #6b7280;
  --muted-2: #939ba7;
  --line: #e4e7ec;
  --line-strong: #cbd2dc;
  --bg: #f5f6f8;
  --bg-2: #eceef2;
  --card: #ffffff;

  --ok: #12795c;
  --ok-soft: #e6f5ef;
  --warn: #a55a05;
  --warn-soft: #fdf1d8;
  --danger: #b3261e;
  --danger-soft: #fdecea;
  --info: #1c4ed8;
  --info-soft: #e8eefd;
  --neutral-soft: #eef0f4;

  /* spacing scale (8pt) */
  --sp-1: 4px;
  --sp-2: 8px;
  --sp-3: 12px;
  --sp-4: 16px;
  --sp-5: 24px;
  --sp-6: 32px;
  --sp-7: 48px;
  --sp-8: 64px;

  /* radii */
  --r-xs: 6px;
  --r-sm: 10px;
  --r: 14px;
  --r-lg: 20px;
  --r-pill: 999px;

  /* elevation */
  --sh-1: 0 1px 2px rgba(16, 24, 40, .05), 0 1px 3px rgba(16, 24, 40, .06);
  --sh-2: 0 6px 18px rgba(16, 24, 40, .10);
  --sh-3: 0 18px 48px rgba(16, 24, 40, .20);

  /* motion */
  --t-fast: 150ms ease;
  --t: 180ms ease;

  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;

  --header-h: 58px;
  --bottom-nav-h: 60px;
  --sidebar-w: 232px;
  --content-max: 1240px;
}

/* ------------------------------------------------------------------ base */

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  overflow-wrap: break-word;
}

body.is-locked { overflow: hidden; }

h1, h2, h3, h4 { margin: 0 0 var(--sp-2); line-height: 1.25; color: var(--ink); }
h1 { font-size: 22px; letter-spacing: -.2px; }
h2 { font-size: 18px; }
h3 { font-size: 16px; }
h4 { font-size: 14px; }
p { margin: 0 0 var(--sp-3); }
a { color: var(--accent-strong); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
button, input, select, textarea { font: inherit; color: inherit; }
[hidden] { display: none !important; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--r-xs);
}

::selection { background: var(--accent-soft); }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: var(--sp-2); top: -60px; z-index: 200;
  background: var(--card); color: var(--ink); padding: var(--sp-2) var(--sp-3);
  border-radius: var(--r-sm); box-shadow: var(--sh-2); transition: top var(--t-fast);
}
.skip-link:focus { top: var(--sp-2); }

/* ------------------------------------------------------------ utilities */

.muted { color: var(--muted); }
.small { font-size: 13px; }
.tiny { font-size: 12px; }
.strong { font-weight: 600; }
.nowrap { white-space: nowrap; }
.row { display: flex; align-items: center; gap: var(--sp-2); flex-wrap: wrap; }
.row-top { align-items: flex-start; }
.spread { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); }
.stack { display: grid; gap: var(--sp-3); }
.stack-sm { display: grid; gap: var(--sp-2); }
.stack-lg { display: grid; gap: var(--sp-5); }
.grow { flex: 1 1 auto; min-width: 0; }
.center { text-align: center; }
.right { text-align: right; }
.mt-2 { margin-top: var(--sp-2); }
.mt-3 { margin-top: var(--sp-3); }
.mt-4 { margin-top: var(--sp-4); }
.mb-0 { margin-bottom: 0; }
.divider { height: 1px; background: var(--line); border: 0; margin: var(--sp-3) 0; }
.clamp-2 {
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ---------------------------------------------------------------- buttons */

.btn {
  --btn-bg: var(--card);
  --btn-fg: var(--ink);
  --btn-bd: var(--line-strong);
  display: inline-flex; align-items: center; justify-content: center; gap: var(--sp-2);
  min-height: 44px; padding: 0 var(--sp-4);
  background: var(--btn-bg); color: var(--btn-fg);
  border: 1px solid var(--btn-bd); border-radius: var(--r-sm);
  font-weight: 600; font-size: 14px; cursor: pointer; text-decoration: none;
  transition: background var(--t-fast), border-color var(--t-fast), color var(--t-fast),
              transform var(--t-fast), box-shadow var(--t-fast);
  white-space: nowrap;
}
.btn:hover { background: var(--bg-2); text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn[disabled], .btn.is-disabled {
  opacity: .55; cursor: not-allowed; transform: none;
  background: var(--neutral-soft); color: var(--muted); border-color: var(--line);
}
.btn-primary { --btn-bg: var(--accent); --btn-fg: #fff; --btn-bd: var(--accent); box-shadow: var(--sh-1); }
.btn-primary:hover { background: var(--accent-strong); border-color: var(--accent-strong); }
.btn-primary[disabled], .btn-primary.is-disabled { box-shadow: none; }
.btn-outline { --btn-bg: transparent; --btn-bd: var(--line-strong); }
.btn-ghost { --btn-bg: transparent; --btn-bd: transparent; color: var(--ink-2); }
.btn-ghost:hover { background: var(--bg-2); }
.btn-danger { --btn-bg: var(--danger); --btn-fg: #fff; --btn-bd: var(--danger); }
.btn-danger:hover { background: #8f1e18; }
.btn-danger-ghost { --btn-bg: transparent; --btn-bd: var(--line-strong); color: var(--danger); }
.btn-danger-ghost:hover { background: var(--danger-soft); }
.btn-sm { min-height: 36px; padding: 0 var(--sp-3); font-size: 13px; border-radius: var(--r-xs); }
.btn-lg { min-height: 50px; padding: 0 var(--sp-5); font-size: 15px; }
.btn-block { width: 100%; }
.btn.is-loading { pointer-events: none; opacity: .8; }

.btn-icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 44px; height: 44px; padding: 0;
  background: transparent; border: 1px solid transparent; border-radius: var(--r-sm);
  cursor: pointer; color: var(--ink-2); transition: background var(--t-fast);
}
.btn-icon:hover { background: var(--bg-2); }
.btn-icon svg { width: 20px; height: 20px; }

.spinner {
  width: 16px; height: 16px; border-radius: 50%;
  border: 2px solid currentColor; border-top-color: transparent;
  display: inline-block; animation: spin .7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ----------------------------------------------------------------- forms */

.field { display: grid; gap: 6px; margin-bottom: var(--sp-3); }
.label { font-size: 13px; font-weight: 600; color: var(--ink-2); }
.label .req-star { color: var(--accent-strong); }
.input, .select, .textarea {
  width: 100%; min-height: 44px; padding: 10px var(--sp-3);
  background: var(--card); color: var(--ink);
  border: 1px solid var(--line-strong); border-radius: var(--r-sm);
  transition: border-color var(--t-fast), box-shadow var(--t-fast);
}
.textarea { min-height: 96px; resize: vertical; line-height: 1.5; }
.select { appearance: none; padding-right: 34px; background-image: none; cursor: pointer; }
.select-wrap { position: relative; }
.select-wrap::after {
  content: ""; position: absolute; right: 14px; top: 50%; width: 8px; height: 8px;
  border-right: 2px solid var(--muted); border-bottom: 2px solid var(--muted);
  transform: translateY(-70%) rotate(45deg); pointer-events: none;
}
.input:focus, .select:focus, .textarea:focus {
  outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-ring);
}
.input[aria-invalid="true"], .select[aria-invalid="true"], .textarea[aria-invalid="true"] {
  border-color: var(--danger); box-shadow: 0 0 0 3px rgba(179, 38, 30, .12);
}
.input::placeholder, .textarea::placeholder { color: var(--muted-2); }
.help { font-size: 12px; color: var(--muted); margin: 0; }
.field-error { font-size: 12px; color: var(--danger); font-weight: 600; margin: 0; min-height: 0; }
.field-error:empty { display: none; }
.input-wrap { position: relative; display: flex; align-items: center; }
.input-wrap .input { padding-right: 40px; }
.input-wrap .input-icon {
  position: absolute; right: 8px; width: 32px; height: 32px; min-height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 0; cursor: pointer; color: var(--muted); border-radius: var(--r-xs);
}
.input-wrap .input-icon:hover { background: var(--bg-2); color: var(--ink); }
.input-wrap .input-icon svg { width: 16px; height: 16px; }
.money-input { display: flex; align-items: center; gap: var(--sp-1); }
.money-input .prefix {
  font-weight: 600; color: var(--muted); padding: 0 var(--sp-1);
}

.checkbox, .radio {
  display: flex; align-items: flex-start; gap: var(--sp-2);
  min-height: 44px; padding: var(--sp-2) var(--sp-2); border-radius: var(--r-xs);
  cursor: pointer; font-size: 14px;
}
.checkbox:hover, .radio:hover { background: var(--bg-2); }
.checkbox input, .radio input { width: 18px; height: 18px; margin-top: 3px; accent-color: var(--accent); flex: none; }
.checkbox-grid { display: grid; grid-template-columns: 1fr; gap: 2px; }

.switch { display: flex; align-items: center; gap: var(--sp-2); min-height: 44px; cursor: pointer; font-size: 14px; font-weight: 600; }
.switch input { position: absolute; opacity: 0; width: 1px; height: 1px; }
.switch .track {
  width: 44px; height: 26px; border-radius: var(--r-pill); background: var(--line-strong);
  position: relative; transition: background var(--t); flex: none;
}
.switch .track::after {
  content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px;
  background: #fff; border-radius: 50%; box-shadow: var(--sh-1); transition: transform var(--t);
}
.switch input:checked + .track { background: var(--accent); }
.switch input:checked + .track::after { transform: translateX(18px); }
.switch input:focus-visible + .track { outline: 2px solid var(--accent); outline-offset: 2px; }

.radio-row { display: flex; gap: var(--sp-2); flex-wrap: wrap; }
.radio-card {
  display: flex; align-items: center; gap: var(--sp-2); min-height: 44px;
  padding: var(--sp-2) var(--sp-4); border: 1px solid var(--line-strong);
  border-radius: var(--r-sm); cursor: pointer; background: var(--card); font-weight: 600; font-size: 14px;
  transition: border-color var(--t-fast), background var(--t-fast);
}
.radio-card input { accent-color: var(--accent); }
.radio-card.is-checked { border-color: var(--accent); background: var(--accent-soft); }

/* -------------------------------------------------------- chips / badges */

.chips { display: flex; flex-wrap: wrap; gap: var(--sp-2); }
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 36px; padding: 0 var(--sp-3);
  background: var(--card); color: var(--ink-2);
  border: 1px solid var(--line-strong); border-radius: var(--r-pill);
  font-size: 13px; font-weight: 600; cursor: pointer;
  transition: background var(--t-fast), color var(--t-fast), border-color var(--t-fast);
}
.chip:hover { background: var(--bg-2); }
.chip.is-active { background: var(--accent); border-color: var(--accent); color: #fff; }
.chip-count { font-size: 11px; background: var(--neutral-soft); color: var(--muted); border-radius: var(--r-pill); padding: 1px 7px; }
.chip.is-active .chip-count { background: rgba(255, 255, 255, .25); color: #fff; }
.chip-static { cursor: default; }
.chip-static:hover { background: var(--card); }

.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 9px; border-radius: var(--r-pill);
  font-size: 12px; font-weight: 700; line-height: 1.4; white-space: nowrap;
}
.badge-stock { background: var(--ok-soft); color: var(--ok); }
.badge-stock.is-low { background: var(--warn-soft); color: var(--warn); }
.badge-stock.is-out { background: var(--neutral-soft); color: var(--muted); }
.badge-reco { background: var(--accent); color: #fff; }
.badge-ok { background: var(--ok-soft); color: var(--ok); }
.badge-warn { background: var(--warn-soft); color: var(--warn); }
.badge-danger { background: var(--danger-soft); color: var(--danger); }
.badge-info { background: var(--info-soft); color: var(--info); }
.badge-neutral { background: var(--neutral-soft); color: var(--muted); }

.tag {
  display: inline-flex; align-items: center;
  padding: 2px 8px; border-radius: var(--r-xs);
  background: var(--bg-2); color: var(--ink-2); font-size: 12px; font-weight: 600;
}
.tag-muted { background: transparent; color: var(--muted); border: 1px solid var(--line); }
.tag-match { background: var(--accent-soft); color: var(--accent-strong); }

.legend {
  display: flex; flex-wrap: wrap; gap: var(--sp-2) var(--sp-4);
  padding: var(--sp-2) var(--sp-3); background: var(--accent-soft);
  border: 1px solid #ffd9c8; border-radius: var(--r-sm); font-size: 12px; color: var(--accent-strong); font-weight: 600;
}
.legend-item { display: inline-flex; align-items: center; gap: 6px; }

/* ----------------------------------------------------------------- cards */

.card {
  background: var(--card); border: 1px solid var(--line);
  border-radius: var(--r); box-shadow: var(--sh-1);
}
.card-pad { padding: var(--sp-4); }
.card-head {
  display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3);
  padding: var(--sp-3) var(--sp-4); border-bottom: 1px solid var(--line);
}
.card-head h2, .card-head h3 { margin: 0; }
.card-body { padding: var(--sp-4); }
.card-foot { padding: var(--sp-3) var(--sp-4); border-top: 1px solid var(--line); background: var(--bg); border-radius: 0 0 var(--r) var(--r); }
.grid-2 { display: grid; grid-template-columns: 1fr; gap: var(--sp-4); }
.grid-3 { display: grid; grid-template-columns: 1fr; gap: var(--sp-4); }

/* ------------------------------------------------------------------ shell */

.app { min-height: 100vh; min-height: 100dvh; display: flex; flex-direction: column; }

.app-header {
  position: sticky; top: 0; z-index: 40;
  background: rgba(255, 255, 255, .96);
  backdrop-filter: saturate(1.4) blur(8px);
  border-bottom: 1px solid var(--line);
}
.app-header-inner {
  max-width: var(--content-max); margin: 0 auto; min-height: var(--header-h);
  padding: 0 var(--sp-3); display: flex; align-items: center; gap: var(--sp-3);
}
.brand { display: inline-flex; align-items: center; gap: var(--sp-2); font-weight: 800; letter-spacing: -.3px; color: var(--ink); text-decoration: none; font-size: 17px; }
.brand:hover { text-decoration: none; }
.brand-mark {
  width: 30px; height: 30px; border-radius: 9px; flex: none;
  background: linear-gradient(140deg, var(--accent), #ff9a3d);
  display: inline-flex; align-items: center; justify-content: center; color: #fff;
}
.brand-mark svg { width: 18px; height: 18px; }
.brand-sub { font-size: 11px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: .8px; }

.nav-primary { display: none; align-items: center; gap: var(--sp-1); margin-left: var(--sp-4); }
.nav-link {
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 38px; padding: 0 var(--sp-3); border-radius: var(--r-sm);
  color: var(--ink-2); font-weight: 600; font-size: 14px; text-decoration: none;
  transition: background var(--t-fast), color var(--t-fast);
}
.nav-link:hover { background: var(--bg-2); text-decoration: none; color: var(--ink); }
.nav-link.is-active { background: var(--accent-soft); color: var(--accent-strong); }
.nav-link svg { width: 18px; height: 18px; }
.header-actions { margin-left: auto; display: flex; align-items: center; gap: var(--sp-1); }

.cart-button { position: relative; }
.cart-button .cart-count {
  position: absolute; top: 2px; right: 0; min-width: 19px; height: 19px; padding: 0 5px;
  border-radius: var(--r-pill); background: var(--accent); color: #fff;
  font-size: 11px; font-weight: 800; display: inline-flex; align-items: center; justify-content: center;
}
.cart-button.is-bumped { animation: bump 420ms ease; }
@keyframes bump {
  0% { transform: scale(1); }
  35% { transform: scale(1.16); }
  60% { transform: scale(.96); }
  100% { transform: scale(1); }
}

.user-chip {
  display: none; align-items: center; gap: var(--sp-2);
  padding: 3px var(--sp-2) 3px 3px; border-radius: var(--r-pill);
  border: 1px solid var(--line); background: var(--card); font-size: 13px; font-weight: 600;
}
.avatar {
  width: 30px; height: 30px; border-radius: 50%; flex: none;
  background: var(--accent-soft); color: var(--accent-strong);
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 12px; text-transform: uppercase;
}
.user-meta { display: grid; line-height: 1.15; }
.user-meta .tiny { color: var(--muted); font-weight: 600; }

.bottom-nav {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 45;
  display: grid; grid-auto-flow: column; grid-auto-columns: 1fr;
  background: rgba(255, 255, 255, .98); border-top: 1px solid var(--line);
  padding-bottom: env(safe-area-inset-bottom);
}
.bottom-nav-item {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  min-height: var(--bottom-nav-h); padding: 6px 2px;
  color: var(--muted); font-size: 11px; font-weight: 700; text-decoration: none;
  background: none; border: 0; cursor: pointer;
}
.bottom-nav-item:hover { text-decoration: none; background: var(--bg-2); }
.bottom-nav-item svg { width: 22px; height: 22px; }
.bottom-nav-item.is-active { color: var(--accent-strong); }
.bottom-nav-item .cart-count { position: absolute; }

/* ----------------------------------------------------------- console shell */

body.is-console { background: var(--bg); }
.console-sidebar {
  background: #171b21; color: #c9d0da; padding: var(--sp-3) var(--sp-2);
  display: flex; flex-direction: column; gap: var(--sp-1);
}
.sidebar-title { font-size: 11px; text-transform: uppercase; letter-spacing: .9px; color: #7b8593; padding: var(--sp-2) var(--sp-3) var(--sp-1); font-weight: 800; }
.sidebar-link {
  display: flex; align-items: center; gap: var(--sp-2);
  min-height: 44px; padding: 0 var(--sp-3); border-radius: var(--r-sm);
  color: #c9d0da; font-weight: 600; font-size: 14px; text-decoration: none;
  transition: background var(--t-fast), color var(--t-fast);
}
.sidebar-link:hover { background: #22282f; color: #fff; text-decoration: none; }
.sidebar-link.is-active { background: var(--accent); color: #fff; }
.sidebar-link svg { width: 18px; height: 18px; }
.console-topbar {
  display: flex; align-items: center; gap: var(--sp-3);
  min-height: var(--header-h); padding: 0 var(--sp-3);
  background: var(--card); border-bottom: 1px solid var(--line);
}

.view { flex: 1 1 auto; min-width: 0; padding: var(--sp-4) var(--sp-3) calc(var(--sp-8) + var(--bottom-nav-h)); outline: none; }
.page { max-width: var(--content-max); margin: 0 auto; }
body.is-console .view { padding-bottom: var(--sp-7); }

.page-head { display: grid; gap: var(--sp-3); margin-bottom: var(--sp-4); }
.page-head h1 { margin: 0; }
.page-sub { margin: 0; color: var(--muted); font-size: 14px; }
.page-head-actions { display: flex; align-items: center; gap: var(--sp-2); flex-wrap: wrap; }

.breadcrumb { font-size: 13px; color: var(--muted); margin-bottom: var(--sp-2); }
.breadcrumb a { color: var(--muted); }
.breadcrumb a:hover { color: var(--accent-strong); }

/* -------------------------------------------------------------- live pill */

.live-pill {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 10px; border-radius: var(--r-pill);
  background: var(--ok-soft); color: var(--ok); font-size: 12px; font-weight: 700;
}
.live-pill .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.live-pill[data-live-state="connecting"] { background: var(--neutral-soft); color: var(--muted); }
.live-pill[data-live-state="open"] .dot { animation: pulse 1.8s ease-in-out infinite; }
.live-pill[data-live-state="error"] { background: var(--warn-soft); color: var(--warn); }
@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: .35; transform: scale(.8); } }

/* --------------------------------------------------------------- toolbar */

.toolbar { padding: var(--sp-3); display: grid; gap: var(--sp-3); margin-bottom: var(--sp-4); }
.toolbar-row { display: flex; align-items: center; gap: var(--sp-3); flex-wrap: wrap; justify-content: space-between; }
.search { position: relative; }
.search .input { padding-left: 38px; }
.search-icon { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); color: var(--muted); pointer-events: none; }
.search-icon svg { width: 17px; height: 17px; }

/* ------------------------------------------------------------ dish cards */

.dish-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: var(--sp-4); }
.dish-card {
  position: relative; display: flex; flex-direction: column; overflow: hidden;
  background: var(--card); border: 1px solid var(--line); border-radius: var(--r);
  box-shadow: var(--sh-1); transition: box-shadow var(--t), border-color var(--t), transform var(--t);
}
.dish-card:hover { box-shadow: var(--sh-2); border-color: var(--line-strong); }
.dish-card.is-recommended { border-color: #ffcdb6; }
.dish-card.is-soldout { opacity: .78; }
.dish-card.is-flash { animation: flash 900ms ease; }
@keyframes flash {
  0% { box-shadow: 0 0 0 0 var(--accent-ring); }
  40% { box-shadow: 0 0 0 4px var(--accent-ring); }
  100% { box-shadow: var(--sh-1); }
}
.dish-media { position: relative; display: block; aspect-ratio: 8 / 5; background: var(--bg-2); overflow: hidden; }
.dish-media img { width: 100%; height: 100%; object-fit: cover; transition: transform var(--t); }
.dish-card:hover .dish-media img { transform: scale(1.03); }
.dish-media .badge-stock { position: absolute; left: var(--sp-2); top: var(--sp-2); box-shadow: var(--sh-1); }
.dish-media .badge-reco { position: absolute; right: var(--sp-2); top: var(--sp-2); }
.dish-body { padding: var(--sp-3); display: flex; flex-direction: column; gap: var(--sp-2); flex: 1 1 auto; }
.dish-name { margin: 0; font-size: 15px; font-weight: 700; }
.dish-name a { color: var(--ink); }
.dish-meta { display: flex; flex-wrap: wrap; gap: 6px; }
.dish-desc { margin: 0; font-size: 13px; color: var(--muted); }
.dish-foot { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); padding-top: var(--sp-1); }
.price { font-size: 17px; font-weight: 800; letter-spacing: -.3px; }
.price-lg { font-size: 24px; font-weight: 800; letter-spacing: -.5px; }
.price-extra { font-size: 12px; color: var(--muted); font-weight: 600; }
.price-strike { color: var(--muted-2); text-decoration: line-through; font-weight: 600; font-size: 14px; }
.why { font-size: 12px; color: var(--accent-strong); font-weight: 600; display: flex; gap: 6px; align-items: flex-start; }

/* ----------------------------------------------------------- dish detail */

.detail { display: grid; gap: var(--sp-4); }
.detail-media { border-radius: var(--r); overflow: hidden; background: var(--bg-2); aspect-ratio: 16 / 10; }
.detail-media img { width: 100%; height: 100%; object-fit: cover; }
.detail-title-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--sp-2); }
.meta-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--sp-3); }
.meta-item { display: grid; gap: 2px; }
.meta-item dt { font-size: 12px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: .5px; margin: 0; }
.meta-item dd { margin: 0; font-size: 14px; font-weight: 600; }

.opt-group { border: 1px solid var(--line); border-radius: var(--r-sm); padding: var(--sp-3); margin: 0 0 var(--sp-3); }
.opt-group.is-missing { border-color: var(--danger); background: var(--danger-soft); }
.opt-group legend { padding: 0 var(--sp-1); font-weight: 700; font-size: 14px; display: inline-flex; align-items: center; gap: var(--sp-2); }
.opt-group .req { font-size: 11px; font-weight: 700; color: var(--danger); background: var(--danger-soft); border-radius: var(--r-pill); padding: 1px 8px; }
.opt-group .opt-hint { font-size: 12px; color: var(--muted); margin: 0 0 var(--sp-2); }
.opt { display: flex; align-items: center; gap: var(--sp-2); min-height: 44px; padding: var(--sp-1) var(--sp-2); border-radius: var(--r-xs); cursor: pointer; }
.opt:hover { background: var(--bg-2); }
.opt input { width: 18px; height: 18px; accent-color: var(--accent); flex: none; }
.opt-name { flex: 1 1 auto; }
.opt-extra { font-size: 12px; font-weight: 700; color: var(--accent-strong); }

.qty { display: inline-flex; align-items: center; border: 1px solid var(--line-strong); border-radius: var(--r-sm); overflow: hidden; background: var(--card); }
.qty-btn {
  width: 40px; height: 40px; min-height: 40px; border: 0; background: var(--card);
  color: var(--ink); font-size: 18px; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; justify-content: center;
}
.qty-btn:hover:not([disabled]) { background: var(--bg-2); }
.qty-btn[disabled] { color: var(--muted-2); cursor: not-allowed; }
.qty-value { min-width: 34px; text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
.sticky-bar {
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 35;
  display: flex; align-items: center; gap: var(--sp-3);
  padding: var(--sp-2) var(--sp-3) calc(var(--sp-2) + env(safe-area-inset-bottom));
  background: var(--card); border-top: 1px solid var(--line); box-shadow: 0 -6px 18px rgba(16, 24, 40, .07);
}

/* ------------------------------------------------------------------ cart */

.overlay {
  position: fixed; inset: 0; z-index: 50; background: rgba(21, 25, 31, .42);
  animation: fade var(--t) ease;
}
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

.cart-drawer, .ai-panel {
  position: fixed; z-index: 60; background: var(--card);
  display: flex; flex-direction: column; box-shadow: var(--sh-3);
}
.cart-drawer { right: 0; top: 0; bottom: 0; width: min(420px, 100%); animation: slide-left var(--t) ease; }
@keyframes slide-left { from { transform: translateX(24px); opacity: .6; } to { transform: none; opacity: 1; } }
.drawer-head {
  display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-4); border-bottom: 1px solid var(--line);
}
.drawer-head h2 { margin: 0; font-size: 16px; }
.drawer-body { flex: 1 1 auto; overflow-y: auto; padding: var(--sp-3) var(--sp-4); -webkit-overflow-scrolling: touch; }
.drawer-foot { border-top: 1px solid var(--line); padding: var(--sp-3) var(--sp-4) calc(var(--sp-3) + env(safe-area-inset-bottom)); background: var(--bg); }

.cart-line { display: grid; grid-template-columns: 62px minmax(0, 1fr); gap: var(--sp-3); padding: var(--sp-3) 0; border-bottom: 1px solid var(--line); }
.cart-line:last-child { border-bottom: 0; }
.cart-line-media { width: 62px; height: 62px; border-radius: var(--r-sm); object-fit: cover; background: var(--bg-2); }
.cart-line-body { display: grid; gap: 4px; min-width: 0; }
.cart-line-name { font-weight: 700; font-size: 14px; }
.cart-line-opts { font-size: 12px; color: var(--muted); }
.cart-line-actions { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); flex-wrap: wrap; }
.line-total { font-weight: 800; font-size: 14px; font-variant-numeric: tabular-nums; }
.cart-summary { display: flex; align-items: center; justify-content: space-between; font-size: 13px; color: var(--muted); font-weight: 600; }
.cart-total { display: flex; align-items: baseline; justify-content: space-between; margin: var(--sp-2) 0 var(--sp-3); }
.cart-total .price { font-size: 22px; }
.cart-empty, .empty-state { text-align: center; padding: var(--sp-6) var(--sp-4); color: var(--muted); }
.cart-empty svg, .empty-state svg { width: 40px; height: 40px; color: var(--muted-2); margin-bottom: var(--sp-2); }
.notice {
  display: flex; gap: var(--sp-2); align-items: flex-start;
  padding: var(--sp-2) var(--sp-3); border-radius: var(--r-sm); font-size: 13px;
  background: var(--info-soft); color: var(--info); border: 1px solid #cddaf8;
}
.notice-warn { background: var(--warn-soft); color: var(--warn); border-color: #f5dfae; }
.notice-danger { background: var(--danger-soft); color: var(--danger); border-color: #f6cec9; }
.notice-ok { background: var(--ok-soft); color: var(--ok); border-color: #c6e8db; }
.notice svg { width: 18px; height: 18px; flex: none; margin-top: 1px; }
.notice ul { margin: var(--sp-1) 0 0; padding-left: var(--sp-4); }

/* -------------------------------------------------------------- ai panel */

.ai-panel { right: 0; top: 0; bottom: 0; width: min(460px, 100%); animation: slide-left var(--t) ease; }
.ai-body { flex: 1 1 auto; overflow-y: auto; padding: var(--sp-3) var(--sp-4) var(--sp-6); display: grid; gap: var(--sp-3); align-content: start; }
.ai-prompt { width: 100%; min-height: 84px; }
.ai-stream {
  margin: 0; padding: var(--sp-3); background: var(--bg); border: 1px solid var(--line);
  border-radius: var(--r-sm); font-family: var(--font); font-size: 13.5px; line-height: 1.6;
  white-space: pre-wrap; word-break: break-word; max-height: 260px; overflow-y: auto;
}
.ai-stream h4 { margin: var(--sp-2) 0 var(--sp-1); font-size: 13px; color: var(--accent-strong); text-transform: uppercase; letter-spacing: .5px; }
.ai-stream ul { margin: 0 0 var(--sp-2); padding-left: var(--sp-4); }
.ai-provider { display: flex; align-items: center; gap: var(--sp-2); font-size: 12px; color: var(--muted); font-weight: 600; }
.ai-card { display: grid; grid-template-columns: 76px minmax(0, 1fr); gap: var(--sp-3); padding: var(--sp-2); border: 1px solid var(--line); border-radius: var(--r-sm); background: var(--card); }
.ai-card img { width: 76px; height: 76px; border-radius: var(--r-xs); object-fit: cover; background: var(--bg-2); }
.ai-card .ai-card-reason { font-size: 12.5px; color: var(--accent-strong); font-weight: 600; margin: var(--sp-1) 0 0; }

/* ------------------------------------------------------------ dialog/toast */

.dialog-host {
  position: fixed; inset: 0; z-index: 80; display: flex; align-items: center; justify-content: center;
  padding: var(--sp-4); background: rgba(21, 25, 31, .45); animation: fade var(--t-fast) ease;
}
.dialog {
  width: 100%; max-width: 440px; max-height: 90vh; display: flex; flex-direction: column;
  background: var(--card); border-radius: var(--r-lg); box-shadow: var(--sh-3);
  animation: pop var(--t) ease;
}
.dialog-lg { max-width: 820px; }
@keyframes pop { from { transform: translateY(10px) scale(.98); opacity: 0; } to { transform: none; opacity: 1; } }
.dialog-head { padding: var(--sp-4) var(--sp-4) var(--sp-2); }
.dialog-head h2 { margin: 0; font-size: 17px; }
.dialog-body { padding: 0 var(--sp-4) var(--sp-4); overflow-y: auto; -webkit-overflow-scrolling: touch; }
.dialog-foot {
  display: flex; gap: var(--sp-2); justify-content: flex-end; flex-wrap: wrap;
  padding: var(--sp-3) var(--sp-4); border-top: 1px solid var(--line); background: var(--bg);
  border-radius: 0 0 var(--r-lg) var(--r-lg);
}
.modal-form-grid { display: grid; grid-template-columns: 1fr; gap: var(--sp-3) var(--sp-4); }

.toast-host {
  position: fixed; z-index: 90; left: var(--sp-3); right: var(--sp-3); bottom: calc(var(--bottom-nav-h) + var(--sp-3));
  display: grid; gap: var(--sp-2); pointer-events: none;
}
.toast {
  pointer-events: auto; display: flex; align-items: flex-start; gap: var(--sp-2);
  padding: var(--sp-3); background: #1f242c; color: #f5f7fa;
  border-radius: var(--r-sm); box-shadow: var(--sh-3); font-size: 14px;
  animation: toast-in var(--t) ease;
}
@keyframes toast-in { from { transform: translateY(8px); opacity: 0; } to { transform: none; opacity: 1; } }
.toast.is-leaving { animation: toast-out var(--t) ease forwards; }
@keyframes toast-out { to { transform: translateY(8px); opacity: 0; } }
.toast-icon { flex: none; margin-top: 1px; }
.toast-icon svg { width: 18px; height: 18px; }
.toast-body { flex: 1 1 auto; min-width: 0; }
.toast-title { font-weight: 700; }
.toast-msg { color: #d5dae2; font-size: 13px; }
.toast-success .toast-icon { color: #6ee7b7; }
.toast-error .toast-icon { color: #fca5a5; }
.toast-warn .toast-icon { color: #fcd34d; }
.toast-info .toast-icon { color: #93c5fd; }
.toast-action {
  background: none; border: 0; color: var(--accent); font-weight: 800; font-size: 13px;
  cursor: pointer; padding: 0; min-height: 24px;
}
.toast-close { background: none; border: 0; color: #9aa3af; cursor: pointer; font-size: 16px; line-height: 1; padding: 2px 4px; }

/* ---------------------------------------------------------------- tables */

.table-wrap { width: 100%; overflow-x: auto; }
.data-table { width: 100%; border-collapse: collapse; font-size: 14px; }
.data-table th, .data-table td { padding: var(--sp-2) var(--sp-3); text-align: left; vertical-align: middle; border-bottom: 1px solid var(--line); }
.data-table thead th {
  font-size: 12px; text-transform: uppercase; letter-spacing: .6px; color: var(--muted);
  background: var(--bg); position: sticky; top: 0; z-index: 1; white-space: nowrap;
}
.data-table tbody tr:hover { background: var(--bg); }
.data-table tbody tr:last-child td { border-bottom: 0; }
.thumb { width: 46px; height: 46px; border-radius: var(--r-xs); object-fit: cover; background: var(--bg-2); flex: none; }
.table-actions { display: flex; gap: var(--sp-1); justify-content: flex-end; }
.cell-name { display: flex; align-items: center; gap: var(--sp-3); min-width: 0; }
.cell-name .name { font-weight: 700; }
.cell-sub { font-size: 12px; color: var(--muted); }

/* --------------------------------------------------------------- pager */

.pager { display: flex; align-items: center; justify-content: center; gap: var(--sp-1); flex-wrap: wrap; margin: var(--sp-5) 0 0; }
.pager-info { width: 100%; text-align: center; font-size: 13px; color: var(--muted); margin-bottom: var(--sp-2); font-weight: 600; }
.pager-num {
  min-width: 40px; min-height: 40px; padding: 0 var(--sp-2); border-radius: var(--r-xs);
  border: 1px solid var(--line-strong); background: var(--card); font-weight: 700; font-size: 13px; cursor: pointer;
}
.pager-num:hover:not([disabled]) { background: var(--bg-2); }
.pager-num.is-active { background: var(--accent); border-color: var(--accent); color: #fff; }
.pager-num[disabled] { opacity: .5; cursor: not-allowed; }
.pager-gap { color: var(--muted); padding: 0 2px; }

/* ---------------------------------------------------- loading / empties */

.skeleton { background: linear-gradient(90deg, var(--bg-2) 25%, #f4f5f7 50%, var(--bg-2) 75%); background-size: 200% 100%; animation: shimmer 1.3s infinite linear; border-radius: var(--r-xs); }
@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
.sk-card { height: 250px; border-radius: var(--r); }
.sk-line { height: 12px; margin-bottom: 8px; }
.loading-block { display: flex; align-items: center; justify-content: center; gap: var(--sp-2); padding: var(--sp-6); color: var(--muted); font-weight: 600; }
.empty-state h3 { margin-bottom: var(--sp-1); }
.empty-state .btn { margin-top: var(--sp-3); }
.error-state { border-color: #f6cec9; background: var(--danger-soft); }

/* ---------------------------------------------------------------- charts */

.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--sp-3); }
.stat-card { padding: var(--sp-3) var(--sp-4); background: var(--card); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--sh-1); }
.stat-label { font-size: 12px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: .5px; }
.stat-value { font-size: 24px; font-weight: 800; letter-spacing: -.5px; margin-top: 2px; font-variant-numeric: tabular-nums; }
.stat-foot { font-size: 12px; color: var(--muted); margin-top: 2px; }

.chart-wrap { position: relative; width: 100%; }
.chart-svg { display: block; width: 100%; height: auto; overflow: visible; }
.chart-svg .grid-line { stroke: var(--line); stroke-width: 1; }
.chart-svg .axis-text { fill: var(--muted); font-size: 11px; font-family: var(--font); }
.chart-svg .bar { fill: var(--accent); transition: opacity var(--t-fast); }
.chart-svg .bar:hover { opacity: .8; }
.chart-svg .bar-alt { fill: #7aa5f5; }
.chart-svg .line-orders { fill: none; stroke: var(--accent); stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.chart-svg .line-revenue { fill: none; stroke: #2f6fed; stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.chart-svg .area-orders { fill: rgba(255, 107, 53, .12); }
.chart-svg .point { stroke: #fff; stroke-width: 2; }
.chart-svg .point-orders { fill: var(--accent); }
.chart-svg .point-revenue { fill: #2f6fed; }
.chart-svg .guide { stroke: var(--line-strong); stroke-width: 1; stroke-dasharray: 3 3; }

.chart-legend { display: flex; flex-wrap: wrap; gap: var(--sp-3); font-size: 12px; color: var(--muted); font-weight: 600; margin-top: var(--sp-2); }
.chart-legend-item { display: inline-flex; align-items: center; gap: 6px; }
.chart-legend .swatch { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
.swatch-orders { background: var(--accent); }
.swatch-revenue { background: #2f6fed; }
.chart-tooltip {
  position: absolute; z-index: 5; pointer-events: none; transform: translate(-50%, -112%);
  background: #1f242c; color: #fff; padding: 6px 9px; border-radius: var(--r-xs);
  font-size: 12px; line-height: 1.35; white-space: nowrap; box-shadow: var(--sh-2);
}
.chart-tooltip strong { display: block; font-size: 11px; color: #cbd5e1; }

.hbar-row { display: grid; grid-template-columns: minmax(80px, 1fr) 2.4fr auto; align-items: center; gap: var(--sp-2); font-size: 13px; }
.hbar-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.hbar-track { height: 10px; border-radius: var(--r-pill); background: var(--bg-2); overflow: hidden; }
.hbar-fill { height: 100%; border-radius: var(--r-pill); background: linear-gradient(90deg, var(--accent), #ff9a3d); }
.hbar-value { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 12px; color: var(--muted); }

.low-stock-list { display: grid; gap: var(--sp-1); }
.low-stock-row { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); padding: var(--sp-2) 0; border-bottom: 1px solid var(--line); font-size: 14px; }
.low-stock-row:last-child { border-bottom: 0; }

/* ----------------------------------------------------------- console bits */

.filters-bar { display: grid; gap: var(--sp-2); padding: var(--sp-3); margin-bottom: var(--sp-4); }
.opt-editor { display: grid; gap: var(--sp-3); }
.opt-group-editor { border: 1px solid var(--line); border-radius: var(--r-sm); padding: var(--sp-3); display: grid; gap: var(--sp-2); background: var(--bg); }
.opt-group-editor .og-head { display: flex; align-items: center; gap: var(--sp-2); flex-wrap: wrap; }
.opt-row { display: grid; grid-template-columns: minmax(0, 1fr) 110px 40px; gap: var(--sp-2); align-items: center; }
.upload-zone { display: grid; gap: var(--sp-2); }
.upload-preview { display: flex; align-items: center; gap: var(--sp-3); }
.upload-preview img { width: 84px; height: 84px; border-radius: var(--r-sm); object-fit: cover; background: var(--bg-2); border: 1px solid var(--line); }
.pick-list { display: grid; gap: var(--sp-1); max-height: 46vh; overflow-y: auto; border: 1px solid var(--line); border-radius: var(--r-sm); padding: var(--sp-2); }
.pick-row { display: grid; grid-template-columns: 26px minmax(0, 1fr) 96px; gap: var(--sp-2); align-items: center; min-height: 52px; padding: var(--sp-1); border-radius: var(--r-xs); }
.pick-row:hover { background: var(--bg); }
.pick-row.is-selected { background: var(--accent-soft); }
.pick-name { font-weight: 600; font-size: 14px; }
.pick-sub { font-size: 12px; color: var(--muted); }
.qty-input { width: 96px; text-align: center; font-variant-numeric: tabular-nums; }

/* ------------------------------------------------------------------ auth */

.auth-shell { display: flex; align-items: center; justify-content: center; min-height: calc(100vh - var(--header-h)); padding: var(--sp-4) var(--sp-3) var(--sp-8); }
.auth-card { width: 100%; max-width: 420px; }
.auth-card .card-pad { padding: var(--sp-5); }
.auth-brand { display: flex; flex-direction: column; align-items: center; gap: var(--sp-2); margin-bottom: var(--sp-4); text-align: center; }
.auth-brand .brand-mark { width: 46px; height: 46px; border-radius: 14px; }
.auth-brand .brand-mark svg { width: 26px; height: 26px; }
.auth-hint { font-size: 12px; color: var(--muted); text-align: center; margin-top: var(--sp-3); }
.demo-hint { background: var(--bg-2); border-radius: var(--r-sm); padding: var(--sp-2) var(--sp-3); font-size: 12px; color: var(--ink-2); }
.order-card { display: grid; gap: var(--sp-2); padding: var(--sp-4); }
.order-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--sp-3); flex-wrap: wrap; }
.order-no { font-family: var(--font-mono); font-size: 13px; color: var(--muted); }
.timeline { display: grid; gap: var(--sp-2); }
.kv { display: flex; align-items: baseline; justify-content: space-between; gap: var(--sp-3); font-size: 14px; padding: 3px 0; }
.kv dt { color: var(--muted); font-weight: 600; margin: 0; }
.kv dd { margin: 0; font-weight: 700; text-align: right; }
.kv-total dd { font-size: 18px; }

/* ------------------------------------------------------------ responsive */

@media (min-width: 640px) {
  body { font-size: 15px; }
  .view { padding: var(--sp-5) var(--sp-4) calc(var(--sp-8) + var(--bottom-nav-h)); }
  .checkbox-grid { grid-template-columns: 1fr 1fr; }
  .modal-form-grid { grid-template-columns: 1fr 1fr; }
  .toast-host { left: auto; right: var(--sp-4); width: 380px; bottom: var(--sp-4); }
  h1 { font-size: 24px; }
}

@media (min-width: 900px) {
  :root { --header-h: 62px; }
  .nav-primary { display: flex; }
  .user-chip { display: inline-flex; }
  .bottom-nav { display: none; }
  .view { padding-bottom: var(--sp-8); }
  .dish-grid { grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); }
  .page-head { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
  .page-head-actions { justify-content: flex-end; }
  .grid-2 { grid-template-columns: 1fr 1fr; }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .detail { grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); align-items: start; }
  .detail-side { position: sticky; top: calc(var(--header-h) + var(--sp-4)); }
  .sticky-bar { display: none; }
  .toolbar { grid-template-columns: minmax(0, 320px) minmax(0, 1fr); align-items: start; }
  .toolbar .toolbar-row { grid-column: 1 / -1; }
  .checkout-layout { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: var(--sp-4); align-items: start; }
  .checkout-aside { position: sticky; top: calc(var(--header-h) + var(--sp-4)); }
  .console-layout { display: grid; grid-template-columns: var(--sidebar-w) minmax(0, 1fr); align-items: start; }
  .console-sidebar { position: sticky; top: var(--header-h); height: calc(100vh - var(--header-h)); overflow-y: auto; }
  .filters-bar { grid-template-columns: minmax(0, 1fr) 200px 160px auto; align-items: center; }
  .cart-drawer, .ai-panel { border-radius: var(--r-lg) 0 0 var(--r-lg); }
}

@media (min-width: 1200px) {
  .dish-grid { grid-template-columns: repeat(auto-fill, minmax(268px, 1fr)); }
  .stat-grid { grid-template-columns: repeat(5, 1fr); }
}

/* Mobile: drawers become bottom sheets, tables become stacked cards */
@media (max-width: 899px) {
  .console-sidebar {
    position: fixed; left: 0; right: 0; bottom: 0; top: auto; z-index: 46;
    flex-direction: row; align-items: center; gap: var(--sp-1); padding: var(--sp-1) var(--sp-2) calc(var(--sp-1) + env(safe-area-inset-bottom));
    border-top: 1px solid #2a313a; overflow-x: auto;
  }
  .console-sidebar .sidebar-title { display: none; }
  .sidebar-link { flex-direction: column; gap: 2px; font-size: 11px; min-width: 88px; padding: 6px var(--sp-2); justify-content: center; }
  body.is-console .view { padding-bottom: calc(var(--sp-7) + var(--bottom-nav-h)); }
}

@media (max-width: 639px) {
  .cart-drawer, .ai-panel {
    left: 0; right: 0; top: auto; bottom: 0; width: 100%;
    max-height: 88vh; border-radius: var(--r-lg) var(--r-lg) 0 0;
    animation: sheet-up var(--t) ease;
  }
  @keyframes sheet-up { from { transform: translateY(18px); opacity: .7; } to { transform: none; opacity: 1; } }
  .cart-drawer::before, .ai-panel::before {
    content: ""; width: 40px; height: 4px; border-radius: var(--r-pill);
    background: var(--line-strong); margin: var(--sp-2) auto 0;
  }
  .drawer-head { padding-top: var(--sp-2); }
  .dialog-foot .btn { flex: 1 1 auto; }

  /* stacked table cards */
  .data-table thead { display: none; }
  .data-table, .data-table tbody, .data-table tr, .data-table td { display: block; width: 100%; }
  .data-table tr {
    border: 1px solid var(--line); border-radius: var(--r-sm);
    margin-bottom: var(--sp-2); padding: var(--sp-2); background: var(--card);
  }
  .data-table td {
    display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3);
    border: 0; padding: 6px var(--sp-1); text-align: right;
  }
  .data-table td::before {
    content: attr(data-label); font-size: 11px; font-weight: 800; color: var(--muted);
    text-transform: uppercase; letter-spacing: .5px; text-align: left; flex: none;
  }
  .data-table td.cell-main { justify-content: flex-start; text-align: left; }
  .data-table td.cell-main::before { display: none; }
  .table-actions { justify-content: flex-end; }
  .opt-row { grid-template-columns: minmax(0, 1fr) 90px 40px; }
  .pick-row { grid-template-columns: 26px minmax(0, 1fr) 84px; }
  .qty-input { width: 84px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important; animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
}

@media print {
  .app-header, .bottom-nav, .cart-drawer, .ai-panel, .overlay, .toast-host { display: none !important; }
}

/* utils.js — formatting, validation, DOM + a11y helpers, tiny UI kit.
 * No dependency on store/api so every other module can import it safely.
 */

/* ------------------------------------------------------------ constants */

export const LIMITS = {
  email: 200,
  passwordMin: 8,
  passwordMax: 72,
  displayName: 100,
  search: 50,
  address: 200,
  prompt: 300,
  dishName: 120,
  dishDescription: 500,
  protein: 120,
  imageUrl: 300,
  optionName: 60,
  groupName: 60,
  maxQuantity: 10000,
  uploadBytes: 5 * 1024 * 1024,
};

export const CATEGORIES = ['Chinese', 'Western', 'Japanese', 'Light Meal', 'Korean', 'Southeast Asian'];
export const SPICE_LEVELS = ['None', 'Mild', 'Medium', 'Hot'];
export const ALLERGENS = ['Peanuts', 'Dairy', 'Egg', 'Gluten', 'Soy', 'Fish', 'Shellfish'];
export const TASTES = ['Light', 'Balanced', 'Rich'];
export const MEAL_PERIODS = ['LUNCH', 'DINNER'];
export const ORDER_STATUSES = ['Pending', 'Confirmed', 'Completed', 'Cancelled'];

/* --------------------------------------------------------------- money */

/** Format integer cents as `¥22.00`. Never uses float arithmetic. */
export function formatCents(cents, symbol = '¥') {
  const n = Number(cents);
  const safe = Number.isFinite(n) ? Math.round(n) : 0;
  const sign = safe < 0 ? '-' : '';
  const abs = Math.abs(safe);
  const whole = Math.floor(abs / 100);
  const frac = String(abs % 100).padStart(2, '0');
  return `${sign}${symbol}${whole}.${frac}`;
}

/** `+¥3.00` for option extras (empty string when there is no extra). */
export function formatExtraCents(cents) {
  const n = Number(cents) || 0;
  return n > 0 ? `+${formatCents(n)}` : '';
}

/** Parse a user typed price into integer cents. Returns null when invalid. */
export function parsePriceToCents(raw) {
  if (raw === null || raw === undefined) return null;
  let s = String(raw).replace(/[¥,\s]/g, '').trim();
  if (s === '') return null;
  if (!/^\d{0,7}(\.\d{0,2})?$/.test(s)) return null;
  if (s === '.') return null;
  const parts = s.split('.');
  const whole = parts[0] === '' ? '0' : parts[0];
  const frac = ((parts[1] || '') + '00').slice(0, 2);
  const cents = Number(whole) * 100 + Number(frac);
  return Number.isSafeInteger(cents) ? cents : null;
}

/** Cents → value for a ¥ text input, e.g. 2250 → "22.50". */
export function centsToInputValue(cents) {
  if (cents === null || cents === undefined || cents === '') return '';
  return (Math.round(Number(cents)) / 100).toFixed(2);
}

/** Sum a list of cent amounts, tolerating nulls. */
export function sumCents(list) {
  return (list || []).reduce((acc, n) => acc + (Number.isFinite(Number(n)) ? Math.round(Number(n)) : 0), 0);
}

/* ---------------------------------------------------------------- text */

export function escapeHtml(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function truncate(value, max) {
  const s = value === null || value === undefined ? '' : String(value);
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

export function capitalize(value) {
  const s = String(value || '');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export function titleCase(value) {
  return String(value || '')
    .toLowerCase()
    .split(/[\s_-]+/)
    .filter(Boolean)
    .map(capitalize)
    .join(' ');
}

export function pluralize(count, singular, plural) {
  return `${count} ${count === 1 ? singular : (plural || `${singular}s`)}`;
}

/** Options list → `Whole Wheat · Mustard · Cheese +¥3.00` */
export function optionsSummary(options) {
  if (!options || !options.length) return '';
  return options
    .map((o) => {
      const name = o.optionName || o.name || '';
      const extra = Number(o.extraPriceCents || 0);
      return extra > 0 ? `${name} ${formatExtraCents(extra)}` : name;
    })
    .join(' · ');
}

/* ------------------------------------------------------------ validate */

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export function validateEmail(value) {
  const v = String(value || '').trim();
  if (!v) return 'Email is required.';
  if (v.length > LIMITS.email) return `Email must be at most ${LIMITS.email} characters.`;
  if (!EMAIL_RE.test(v)) return 'Enter a valid email address, e.g. name@company.com.';
  return '';
}

export function validatePassword(value, { required = true } = {}) {
  const v = String(value || '');
  if (!v) return required ? 'Password is required.' : '';
  if (v.length < LIMITS.passwordMin) return `Password must be at least ${LIMITS.passwordMin} characters.`;
  if (v.length > LIMITS.passwordMax) return `Password must be at most ${LIMITS.passwordMax} characters.`;
  if (!/[A-Za-z]/.test(v) || !/\d/.test(v)) return 'Password must contain at least one letter and one digit.';
  return '';
}

export function validateDisplayName(value) {
  const v = String(value || '').trim();
  if (!v) return 'Display name is required.';
  if (v.length > LIMITS.displayName) return `Display name must be at most ${LIMITS.displayName} characters.`;
  return '';
}

export function validateAddress(value) {
  const v = String(value || '').trim();
  if (!v) return 'Delivery address is required.';
  if (v.length > LIMITS.address) return `Address must be at most ${LIMITS.address} characters.`;
  return '';
}

export function validateSearch(value) {
  const v = String(value || '');
  if (v.length > LIMITS.search) return `Search must be at most ${LIMITS.search} characters.`;
  return '';
}

export function validatePrompt(value) {
  const v = String(value || '').trim();
  if (!v) return 'Please describe what you feel like eating.';
  if (v.length > LIMITS.prompt) return `Keep it under ${LIMITS.prompt} characters.`;
  return '';
}

export function validateBudgets(minCents, maxCents) {
  const errs = {};
  const inRange = (c) => c === null || c === undefined || (c >= 0 && c <= 100000);
  if (!inRange(minCents)) errs.budgetMinCents = 'Minimum budget must be between ¥0.00 and ¥1000.00.';
  if (!inRange(maxCents)) errs.budgetMaxCents = 'Maximum budget must be between ¥0.00 and ¥1000.00.';
  if (!errs.budgetMinCents && !errs.budgetMaxCents && minCents !== null && maxCents !== null && minCents > maxCents) {
    errs.budgetMinCents = 'Minimum budget cannot be greater than the maximum.';
  }
  return errs;
}

/** Set or clear an inline field error. */
export function setFieldError(form, name, message) {
  const input = form.querySelector(`[name="${name}"]`);
  const slot = form.querySelector(`[data-error-for="${name}"]`);
  if (input && input.matches('input, select, textarea')) input.setAttribute('aria-invalid', message ? 'true' : 'false');
  if (slot) slot.textContent = message || '';
}

export function clearFieldErrors(form) {
  form.querySelectorAll('[data-error-for]').forEach((el) => { el.textContent = ''; });
  form.querySelectorAll('[aria-invalid]').forEach((el) => el.setAttribute('aria-invalid', 'false'));
}

export function applyFieldErrors(form, fieldErrors) {
  clearFieldErrors(form);
  let first = null;
  Object.entries(fieldErrors || {}).forEach(([name, message]) => {
    setFieldError(form, name, message);
    if (!first) first = form.querySelector(`[name="${name}"]`);
  });
  if (first && typeof first.focus === 'function') first.focus();
  return Boolean(first);
}

/* --------------------------------------------------------- timing / async */

export function debounce(fn, wait = 300) {
  let timer = null;
  const wrapped = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => { timer = null; fn(...args); }, wait);
  };
  wrapped.cancel = () => { clearTimeout(timer); timer = null; };
  wrapped.flush = (...args) => { clearTimeout(timer); timer = null; fn(...args); };
  return wrapped;
}

export function throttle(fn, wait = 250, { leading = true, trailing = true } = {}) {
  let last = 0;
  let timer = null;
  let lastArgs = null;
  return (...args) => {
    const now = Date.now();
    lastArgs = args;
    if (leading && now - last >= wait) {
      last = now;
      fn(...args);
      return;
    }
    if (trailing && !timer) {
      timer = setTimeout(() => {
        timer = null;
        last = Date.now();
        fn(...lastArgs);
      }, Math.max(0, wait - (now - last)));
    }
  };
}

const clickGates = new WeakMap();

/** True when the same element was activated again inside `ms` (repeat-click guard). */
export function isRepeatClick(el, ms = 250) {
  const now = Date.now();
  const last = clickGates.get(el) || 0;
  if (now - last < ms) return true;
  clickGates.set(el, now);
  return false;
}

export function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Mark a button as busy without losing its label. */
export function setBusy(button, busy, busyLabel = 'Working…') {
  if (!button) return;
  if (busy) {
    if (!button.dataset.originalHtml) button.dataset.originalHtml = button.innerHTML;
    if (!button.disabled) button.dataset.wasDisabled = 'false';
    button.disabled = true;
    button.setAttribute('aria-busy', 'true');
    button.classList.add('is-loading');
    button.innerHTML = `<span class="spinner" aria-hidden="true"></span><span>${escapeHtml(busyLabel)}</span>`;
  } else {
    button.disabled = false;
    button.removeAttribute('aria-busy');
    button.classList.remove('is-loading');
    if (button.dataset.originalHtml) {
      button.innerHTML = button.dataset.originalHtml;
      delete button.dataset.originalHtml;
    }
  }
}

/* --------------------------------------------------------------- dates */

function pad2(n) { return String(n).padStart(2, '0'); }

export function todayStr(base = new Date()) {
  return `${base.getFullYear()}-${pad2(base.getMonth() + 1)}-${pad2(base.getDate())}`;
}

export function shiftDate(dateStr, days) {
  const d = parseDate(dateStr);
  d.setDate(d.getDate() + days);
  return todayStr(d);
}

export function tomorrowStr() { return shiftDate(todayStr(), 1); }

export function parseDate(dateStr) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(dateStr || ''));
  if (!m) return new Date();
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}

export function formatDate(dateStr) {
  if (!dateStr) return '—';
  const d = parseDate(dateStr);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

export function formatDateShort(dateStr) {
  if (!dateStr) return '—';
  const d = parseDate(dateStr);
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

export function formatWeekday(dateStr) {
  return parseDate(dateStr).toLocaleDateString('en-US', { weekday: 'short' });
}

export function formatTime(value) {
  if (!value) return '—';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
}

export function formatDateTime(value) {
  if (!value) return '—';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '—';
  return `${d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}, ${formatTime(value)}`;
}

export function dayLabel(dateStr) {
  if (!dateStr) return '—';
  const today = todayStr();
  if (dateStr === today) return 'Today';
  if (dateStr === tomorrowStr()) return 'Tomorrow';
  if (dateStr === shiftDate(today, -1)) return 'Yesterday';
  return formatDateShort(dateStr);
}

export function mealPeriodLabel(period) {
  if (period === 'LUNCH') return 'Lunch';
  if (period === 'DINNER') return 'Dinner';
  return '—';
}

export function spiceLabel(level) {
  if (!level || level === 'None') return 'No spice';
  return `${level} spice`;
}

