#!/usr/bin/env python3
"""Read-only helper: strip ESM import/export syntax so a plain JS engine can parse each file."""
import os
import sys

ROOT = "/Users/anthonyzhi/Documents/Qoder/2026-09-17/e02f265e/webox/frontend/js"
OUT = "/tmp/jscheck"


def balance(line):
    depth = 0
    quote = None
    escaped = False
    for ch in line:
        if quote:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == quote:
                quote = None
            continue
        if ch in "\"'`":
            quote = ch
            continue
        if ch in "({[":
            depth += 1
        elif ch in ")}]":
            depth -= 1
    return depth


def transform(src):
    lines = src.split("\n")
    out = []
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        depth = balance(line)
        if stripped.startswith("import ") or stripped.startswith("import{") or stripped.startswith('import"'):
            while depth > 0 or not stripped.endswith(";"):
                i += 1
                if i >= len(lines):
                    break
                stripped = lines[i].strip()
                depth += balance(lines[i])
            i += 1
            continue
        if stripped.startswith("export {"):
            while not stripped.endswith(";"):
                i += 1
                if i >= len(lines):
                    break
                stripped = lines[i].strip()
            i += 1
            continue
        if stripped.startswith("export default "):
            out.append(line.replace("export default ", "", 1))
            i += 1
            continue
        if stripped.startswith("export "):
            out.append(line.replace("export ", "", 1))
            i += 1
            continue
        out.append(line)
        i += 1
    return "\n".join(out)


def main():
    os.makedirs(OUT, exist_ok=True)
    count = 0
    for dirpath, _dirs, files in os.walk(ROOT):
        for name in sorted(files):
            if not name.endswith(".js"):
                continue
            path = os.path.join(dirpath, name)
            with open(path, "r", encoding="utf-8") as handle:
                src = handle.read()
            rel = os.path.relpath(path, ROOT).replace("/", "__")
            with open(os.path.join(OUT, rel), "w", encoding="utf-8") as handle:
                handle.write(transform(src))
            count += 1
    print(f"transformed {count} files into {OUT}")


if __name__ == "__main__":
    sys.exit(main())

ObjC.import('Foundation');

var dir = '/tmp/jscheck';
var fm = $.NSFileManager.defaultManager;
var listing = fm.contentsOfDirectoryAtPathError(dir, null);
var names = [];
for (var i = 0; i < listing.count; i++) {
  names.push(ObjC.unwrap(listing.objectAtIndex(i)));
}
names.sort();

var syntaxErrors = [];
var runtimeErrors = [];
var ok = 0;

for (var n = 0; n < names.length; n++) {
  var name = names[n];
  if (name.indexOf('.js') !== name.length - 3) continue;
  var path = dir + '/' + name;
  var source = $.NSString.stringWithContentsOfFileEncodingError(path, $.NSUTF8StringEncoding, null);
  if (!source || !source.js) { runtimeErrors.push(name + ': <unreadable>'); continue; }
  try {
    eval(source.js);
    ok++;
  } catch (err) {
    var text = String(err);
    if (text.indexOf('SyntaxError') >= 0) syntaxErrors.push(name + ': ' + text);
    else runtimeErrors.push(name + ': ' + text.split('\n')[0]);
  }
}

'SYNTAX ERRORS (' + syntaxErrors.length + ')';
syntaxErrors.join('\n---\n');
'RUNTIME-ONLY (syntax ok) (' + runtimeErrors.length + ')';
runtimeErrors.join('\n---\n');
'PARSED CLEAN: ' + ok;

#!/usr/bin/env python3
"""Read-only static checks for the WeBox frontend JS:
1. delimiter balance + unterminated string/comment scan
2. named import/export cross-check between modules (catches missing exports)
3. duplicate top-level declarations
No file is modified.
"""
import os
import re
import sys

ROOT = "/Users/anthonyzhi/Documents/Qoder/2026-09-17/e02f265e/webox/frontend"

problems = []


def strip_noise(src):
    """Remove comments and string/template contents, keeping delimiters."""
    out = []
    i = 0
    n = len(src)
    quote = None
    while i < n:
        ch = src[i]
        nxt = src[i + 1] if i + 1 < n else ""
        if quote:
            if ch == "\\":
                i += 2
                continue
            if ch == quote:
                quote = None
                out.append(ch)
            else:
                out.append(" ")
            i += 1
            continue
        if ch in "\"'`":
            quote = ch
            out.append(ch)
            i += 1
            continue
        if ch == "/" and nxt == "/":
            while i < n and src[i] != "\n":
                i += 1
            continue
        if ch == "/" and nxt == "*":
            i += 2
            while i < n - 1 and not (src[i] == "*" and src[i + 1] == "/"):
                i += 1
            i += 2
            continue
        out.append(ch)
        i += 1
    return "".join(out)


def scan_delimiters(path, src):
    clean = strip_noise(src)
    stack = []
    pairs = {")": "(", "]": "[", "}": "{"}
    line = 1
    for ch in clean:
        if ch == "\n":
            line += 1
        elif ch in "([{":
            stack.append((ch, line))
        elif ch in ")]}":
            if not stack:
                problems.append(f"{path}:{line}: unmatched closing '{ch}'")
                return
            opener, oline = stack.pop()
            if opener != pairs[ch]:
                problems.append(f"{path}:{line}: '{ch}' closes '{opener}' opened at line {oline}")
                return
    for opener, oline in stack:
        problems.append(f"{path}: unclosed '{opener}' opened at line {oline}")


IMPORT_RE = re.compile(r"import\s+(?:\{([^}]*)\}|(\w+)\s*,\s*\{([^}]*)\})\s+from\s+['\"]([^'\"]+)['\"]|import\s+(\w+)\s+from\s+['\"]([^'\"]+)['\"]")
EXPORT_RE = re.compile(r"export\s+(?:async\s+)?(?:function|const|let|var|class)\s+(\w+)")
EXPORT_LIST_RE = re.compile(r"export\s*\{([^}]*)\}")


def exports_of(src):
    names = set(EXPORT_RE.findall(src))
    for group in EXPORT_LIST_RE.findall(src):
        for part in group.split(","):
            part = part.strip()
            if not part:
                continue
            names.add(part.split(" as ")[-1].strip())
    return names


def local_decls(src):
    return set(re.findall(r"^\s*(?:async\s+)?function\s+(\w+)", src, re.M)) | \
           set(re.findall(r"^\s*(?:const|let|var)\s+(\w+)\s*=", src, re.M))


def main():
    files = {}
    for dirpath, _dirs, names in os.walk(ROOT):
        if "assets" in dirpath:
            continue
        for name in names:
            if name.endswith(".js"):
                path = os.path.join(dirpath, name)
                with open(path, "r", encoding="utf-8") as handle:
                    files[path] = handle.read()

    for path, src in files.items():
        rel = os.path.relpath(path, ROOT)
        scan_delimiters(rel, src)

        for match in IMPORT_RE.finditer(src):
            groups = [g for g in (match.group(1), match.group(3)) if g]
            target = match.group(4) or match.group(6)
            default_name = match.group(2) or match.group(5)
            if target and not target.startswith("."):
                continue
            target_path = os.path.normpath(os.path.join(os.path.dirname(path), target))
            if not os.path.exists(target_path):
                problems.append(f"{rel}: import target missing: {target}")
                continue
            available = exports_of(files.get(target_path, ""))
            for group in groups:
                for part in group.split(","):
                    part = part.strip()
                    if not part:
                        continue
                    imported = part.split(" as ")[0].strip()
                    if imported and imported not in available:
                        problems.append(
                            f"{rel}: imports '{imported}' from {target} but it is not exported there"
                        )
            if default_name:
                # our modules never export defaults
                problems.append(f"{rel}: default import '{default_name}' from {target} (no default exports exist)")

        seen = {}
        for decl in re.findall(r"^\s*(?:async\s+)?(?:function|const|let|var)\s+(\w+)", src, re.M):
            seen[decl] = seen.get(decl, 0) + 1
        for decl, count in seen.items():
            if count > 1 and re.search(rf"^\s*(?:async\s+)?function\s+{decl}\b", src, re.M):
                # function declarations may not be duplicated at top level
                problems.append(f"{rel}: duplicate function declaration '{decl}'")

    if problems:
        print(f"{len(problems)} problem(s):")
        for problem in problems:
            print(" -", problem)
        return 1
    print(f"clean: {len(files)} files, no delimiter/import problems detected")
    return 0


if __name__ == "__main__":
    sys.exit(main())

