32	/* --------------------------------------------------------------- money */
33	
34	/** Format integer cents as `¥22.00`. Never uses float arithmetic. */
35	export function formatCents(cents, symbol = '¥') {
36	  const n = Number(cents);
37	  const safe = Number.isFinite(n) ? Math.round(n) : 0;
38	  const sign = safe < 0 ? '-' : '';
39	  const abs = Math.abs(safe);
40	  const whole = Math.floor(abs / 100);
41	  const frac = String(abs % 100).padStart(2, '0');
42	  return `${sign}${symbol}${whole}.${frac}`;
43	}
44	
45	/** `+¥3.00` for option extras (empty string when there is no extra). */
46	export function formatExtraCents(cents) {
47	  const n = Number(cents) || 0;
48	  return n > 0 ? `+${formatCents(n)}` : '';
49	}
50	
51	/** Parse a user typed price into integer cents. Returns null when invalid. */
52	export function parsePriceToCents(raw) {
53	  if (raw === null || raw === undefined) return null;
54	  let s = String(raw).replace(/[¥,\s]/g, '').trim();
55	  if (s === '') return null;
56	  if (!/^\d{0,7}(\.\d{0,2})?$/.test(s)) return null;
57	  if (s === '.') return null;
58	  const parts = s.split('.');
59	  const whole = parts[0] === '' ? '0' : parts[0];
60	  const frac = ((parts[1] || '') + '00').slice(0, 2);
61	  const cents = Number(whole) * 100 + Number(frac);
62	  return Number.isSafeInteger(cents) ? cents : null;
63	}
64	
65	/** Cents → value for a ¥ text input, e.g. 2250 → "22.50". */
66	export function centsToInputValue(cents) {
67	  if (cents === null || cents === undefined || cents === '') return '';
68	  return (Math.round(Number(cents)) / 100).toFixed(2);
69	}
70	
71	/** Sum a list of cent amounts, tolerating nulls. */
72	export function sumCents(list) {
73	  return (list || []).reduce((acc, n) => acc + (Number.isFinite(Number(n)) ? Math.round(Number(n)) : 0), 0);
74	}
