78	export function escapeHtml(value) {
79	  if (value === null || value === undefined) return '';
80	  return String(value)
81	    .replace(/&/g, '&amp;')
82	    .replace(/</g, '&lt;')
83	    .replace(/>/g, '&gt;')
84	    .replace(/"/g, '&quot;')
85	    .replace(/'/g, '&#39;');
