93	export function capitalize(value) {
94	  const s = String(value || '');
95	  return s.charAt(0).toUpperCase() + s.slice(1);
96	}
97	
98	export function titleCase(value) {
99	  return String(value || '')
100	    .toLowerCase()
101	    .split(/[\s_-]+/)
102	    .filter(Boolean)
103	    .map(capitalize)
104	    .join(' ');
