99	function resolveGuard(matched) {
100	  const { route } = matched;
101	  const authed = isAuthenticated();
102	  const user = getUser();
103	  const role = user?.role;
104	
105	  if (route.access === 'public') {
106	    if (authed && (role === 'ADMIN' || role === 'EMPLOYEE')) {
107	      return { redirect: roleHome(role) };
108	    }
109	    if (authed && role !== 'EMPLOYEE' && role !== 'ADMIN') {
110	      // Unknown role: never let an unknown principal roam the app.
111	      clearAuth();
112	      return { redirect: '#/login' };
113	    }
114	    return { ok: true };
115	  }
116	
117	  if (!authed) {
118	    const next = encodeURIComponent(`#${current.path}`);
119	    return { redirect: `#/login?next=${next}` };
120	  }
121	
122	  if (role !== 'EMPLOYEE' && role !== 'ADMIN') {
123	    clearAuth();
124	    toast('Your account role is not recognised. Please sign in again.', { type: 'warn' });
125	    return { redirect: '#/login' };
126	  }
127	
128	  if (route.access === 'admin' && !isAdmin()) {
129	    return { ok: true, denied: accessDeniedHtml('The Console is available to administrators only. Your account has employee access.') };
130	  }
131	
132	  if (route.access === 'employee' && isAdmin()) {
133	    return { redirect: '/console/dashboard', notice: 'The Console is your home — employee ordering screens are hidden for admin accounts.' };
134	  }
135	
136	  return { ok: true };
137	}
