141	export async function render() {
142	  if (!container) return;
143	  const { path, query } = parseHash();
144	  current = { path, query, params: {} };
145	
146	  // Default landing per role.
147	  if (path === '/' || path === '/home' || path === '/index.html') {
148	    navigate(roleHome(), { replace: true });
149	    return;
150	  }
151	
152	  const matched = matchRoute(path);
153	  const token = ++renderToken;
154	
155	  if (!matched) {
156	    teardown();
157	    document.title = 'Not found · WeBox';
158	    container.innerHTML = `<section class="page">${emptyStateHtml({
159	      title: 'Page not found',
160	      message: `No screen matches “${path}”. Use the navigation to keep browsing.`,
161	      actionLabel: 'Back to menu',
162	      actionAttrs: `data-nav="${roleHome()}"`,
163	      iconName: 'alert',
164	    })}</section>`;
165	    wireCommonNav();
166	    notify({ ...current, notFound: true });
167	    return;
168	  }
169	
170	  const guard = resolveGuard(matched);
171	  if (guard.redirect) {
172	    if (guard.notice) toast(guard.notice, { type: 'info' });
173	    navigate(guard.redirect, { replace: true });
174	    return;
175	  }
176	
177	  teardown();
178	  current = { path, query, params: matched.params, route: matched.route };
179	  setState({ route: current });
180	  document.title = `${matched.route.title} · WeBox`;
181	  container.setAttribute('aria-busy', 'false');
182	  window.scrollTo({ top: 0, behavior: 'auto' });
183	
184	  if (guard.denied) {
185	    container.innerHTML = guard.denied;
186	    notify(current);
187	    return;
188	  }
189	
190	  container.innerHTML = '';
191	  try {
192	    const result = await matched.route.render(container, { ...matched.params, query });
193	    if (token !== renderToken) {
194	      // A newer navigation already happened — discard this page's cleanup.
195	      if (typeof result === 'function') result();
196	      return;
197	    }
198	    cleanup = typeof result === 'function' ? result : () => {};
199	  } catch (err) {
200	    if (err?.name === 'AbortError') return;
201	    console.error('[router] page render failed', err);
202	    container.innerHTML = `<section class="page"><div class="card empty-state error-state">
203	      <h3>This page failed to load</h3>
204	      <p class="muted">${escapeHtml(err?.message || 'Unexpected error.')}</p>
205	      <button class="btn btn-outline" data-nav="${roleHome()}">Go to my home</button>
206	    </div></section>`;
207	    wireCommonNav();
208	  }
209	
210	  notify(current);
211	}
